"use client";

import { DEFAULT_PROJECTS, ProjectDeck, type Project } from "@/components/ui/scroll-stacking-cards";

// the four built-in sites plus three more, screenshots embedded so the demo needs no network
const projects: Project[] = [
  ...DEFAULT_PROJECTS,
  { name: "PosFlex", summary: "A growth marketing site for local businesses, with its own AI assistant and CRM.", url: "https://posflexgrowth.com", image: "data:image/webp;base64,", accent: "#0E1B33" },
  { name: "Feisst Electrical", summary: "A new website for a Waikato electrical contractor working on stadiums, homes and solar since 1985.", url: "https://feisst-website.aakashchan113.workers.dev", display: "Preview of the new site", image: "data:image/webp;base64,", accent: "#C8102E" },
  { name: "NamSan 203", summary: "A redesign for a guesthouse beside Namsan in Seoul, with the only camper van stay on the mountain.", url: "https://namsan203.com", image: "data:image/webp;base64,", accent: "#1F2A4A" },
];

export default function ProjectDeckDemo() {
  return (
    <main className="min-h-dvh w-full bg-[#E7E8EA] font-sans text-[#141414]">
      <h1 className="sr-only">Websites by Aakash Mehra</h1>

      <ProjectDeck projects={projects} />

      <footer className="mx-auto max-w-[1180px] px-4 pt-[10vh] pb-10 sm:px-8">
        <p className="m-0 text-[clamp(40px,7vw,104px)] leading-[0.95] font-semibold tracking-[-0.045em]">Yours could be next.</p>
        <p className="mt-6 mb-0 text-[16px]">
          by{" "}
          <a href="https://aakashmehra.com/ref/projectdeck" target="_blank" rel="noopener noreferrer" className="font-semibold underline-offset-4 hover:underline">
            aakashmehra.com
          </a>
        </p>
      </footer>
    </main>
  );
}
